// Validate input and set defaults
const body = $input.first().json.body || $input.first().json;

const prompt = (body.prompt || '').trim();
const profile = body.profile || null;
const target = body.target || 'teams';
const excludeIds = body.exclude_ids || [];
const limit = Math.min(Math.max(body.limit || 5, 1), 20);
const feedback = body.feedback || {};
const weights = feedback.weights || { interest: 0.35, role: 0.35, avail: 0.30 };
const declined = feedback.declined || [];

if (!prompt && !profile) {
  throw new Error('Either prompt or profile is required');
}
if (prompt.length > 1000) {
  throw new Error('Prompt too long (max 1000 chars)');
}

return [{ json: { prompt, profile, target, excludeIds, limit, weights, declined } }];

