// Parse and repair the LLM extraction output
const input = $input.first().json;
let profile;

try {
  // Gemini returns { candidates: [{ content: { parts: [{ text }] } }] }
  let text = '';
  if (input.candidates && input.candidates[0]) {
    text = input.candidates[0].content.parts[0].text;
  } else if (input.error) {
    throw new Error('LLM error: ' + JSON.stringify(input.error));
  } else {
    text = JSON.stringify(input);
  }

  // Strip code fences if present
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  profile = JSON.parse(text);
} catch (e) {
  // Fallback: simple keyword extraction from the original prompt
  const prompt = $('Validate input').first().json.prompt || '';
  const words = prompt.toLowerCase().split(/[\s,;.]+/).filter(w => w.length > 2);
  const roleList = ['frontend developer','backend developer','fullstack developer','mobile developer','ml engineer','data scientist','ux designer','ui designer','product manager','marketing','media','business','hardware','devops engineer'];
  const foundRoles = roleList.filter(r => words.some(w => r.includes(w)));
  profile = {
    idea: null,
    interests: words.slice(0, 5),
    skills: words.filter(w => !['want','build','have','good','would','like','play','role'].includes(w)).slice(0, 5),
    roles: foundRoles.length > 0 ? foundRoles : ['fullstack developer'],
    availability: null,
    synonyms: words.slice(0, 4)
  };
}

// Normalise
const ROLES = ['frontend developer','backend developer','fullstack developer','mobile developer','ml engineer','data scientist','ux designer','ui designer','product manager','marketing','media','business','hardware','devops engineer'];
if (profile.roles) {
  profile.roles = profile.roles.map(r => {
    const low = r.toLowerCase().trim();
    return ROLES.find(cr => cr === low) || low;
  });
}
if (profile.skills) profile.skills = profile.skills.map(s => s.toLowerCase().trim());
if (profile.interests) profile.interests = profile.interests.map(i => i.toLowerCase().trim());
if (!profile.synonyms) profile.synonyms = [];

return [{ json: { profile, prompt: $('Validate input').first().json.prompt } }];

// Build the query text and embedding text from the profile
const data = $input.first().json;
const profile = data.profile;

const parts = [
  profile.idea || '',
  ...(profile.interests || []),
  ...(profile.synonyms || []),
  ...(profile.skills || []),
  ...(profile.roles || [])
].filter(Boolean);

const queryText = parts.join(' ');
const embedText = [profile.idea || '', ...(profile.interests || []), ...(profile.roles || [])].filter(Boolean).join(' ');

return [{ json: { ...data, queryText, embedText } }];

// Re-rank and diversify candidates
// Source of truth: n8n/src/rerank.js

const DEFAULT_WEIGHTS = { interest: 0.35, role: 0.35, avail: 0.30 };

const ADJACENCY = {
  'fullstack developer': { 'frontend developer': 0.6, 'backend developer': 0.6 },
  'ml engineer': { 'data scientist': 0.6 },
  'data scientist': { 'ml engineer': 0.6 },
  'ux designer': { 'ui designer': 0.8 },
  'ui designer': { 'ux designer': 0.8 },
  'product manager': { 'business': 0.6 },
  'business': { 'product manager': 0.6 },
  'marketing': { 'media': 0.6 },
  'media': { 'marketing': 0.6 },
};

function normaliseWeights(w) {
  const sum = Object.values(w).reduce((a, b) => a + b, 0);
  if (sum === 0) return { ...DEFAULT_WEIGHTS };
  const out = {};
  for (const k of Object.keys(w)) out[k] = w[k] / sum;
  return out;
}

function roleFit(userRoles, neededRoles) {
  if (!neededRoles || neededRoles.length === 0) return { score: 0, matched: null };
  const needed = new Set(neededRoles.map(r => r.toLowerCase()));
  const primary = (userRoles[0] || '').toLowerCase();
  if (needed.has(primary)) return { score: 1.0, matched: primary };
  const adj = ADJACENCY[primary] || {};
  for (const [adjRole, strength] of Object.entries(adj)) {
    if (needed.has(adjRole)) return { score: strength, matched: adjRole };
  }
  for (let i = 1; i < userRoles.length; i++) {
    const role = userRoles[i].toLowerCase();
    if (needed.has(role)) return { score: 0.8, matched: role };
    const adjSec = ADJACENCY[role] || {};
    for (const [adjRole, strength] of Object.entries(adjSec)) {
      if (needed.has(adjRole)) return { score: strength * 0.8, matched: adjRole };
    }
  }
  return { score: 0, matched: null };
}

function dupPenalty(userRoles, memberRoles) {
  if (!memberRoles || memberRoles.length === 0) return 0;
  const memberSet = new Set(memberRoles.map(r => r.toLowerCase()));
  let overlapping = 0;
  for (const r of userRoles) { if (memberSet.has(r.toLowerCase())) overlapping++; }
  return Math.min(0.3, 0.15 * overlapping);
}

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

// Main
const inputData = $('Validate input').first().json;
const profile = $('Build query').first().json.profile || $('Build query').first().json.profile;
const candidates = Array.isArray($input.first().json) ? $input.first().json : ($input.first().json.body || []);
const weights = normaliseWeights(inputData.weights || DEFAULT_WEIGHTS);
const excludeSet = new Set(inputData.excludeIds || []);
const limit = inputData.limit || 5;
const userRoles = (profile.roles || []).map(r => r.toLowerCase());

let filtered = candidates.filter(c => !excludeSet.has(c.id));

const scored = filtered.map(c => {
  const interest = clamp(c.rrf || 0, 0, 1);
  const rf = roleFit(userRoles, c.needed_roles);
  const rawAvail = c.overlap != null ? c.overlap : 1.0;
  const avail = clamp((rawAvail - 0.5) / 0.5, 0, 1);
  const penalty = dupPenalty(userRoles, c.member_roles);
  const raw = weights.interest * interest + weights.role * rf.score + weights.avail * avail - penalty;
  const score = clamp(raw, 0, 1);
  return {
    id: c.id, name: c.name, challenge: c.challenge, zone: c.zone,
    members: c.members || 0, max_size: c.max_size || 5,
    needed_roles: c.needed_roles || [],
    fit: Math.round(score * 100),
    factors: {
      interest: Math.round(interest * 100) / 100,
      role: Math.round(rf.score * 100) / 100,
      avail: Math.round(avail * 100) / 100,
    },
    matched_role: rf.matched,
    matched_skills: [],
    score,
  };
});

scored.sort((a, b) => b.score - a.score);

// MMR diversify
const picked = [];
const remaining = [...scored];
while (picked.length < limit && remaining.length > 0) {
  for (const r of remaining) {
    let cp = 0;
    for (const p of picked) {
      if (p.challenge && r.challenge && p.challenge.toLowerCase() === r.challenge.toLowerCase()) cp += 0.1;
    }
    r._adj = r.score - cp;
  }
  remaining.sort((a, b) => b._adj - a._adj);
  const best = remaining.shift();
  if (best) { delete best._adj; picked.push(best); }
}

return [{ json: { profile, results: picked, candidateCount: candidates.length, weights } }];

