// Attach LLM reasons to result cards, with fallback
const reranked = $('Re-rank & diversify').first().json;
const llmOutput = $input.first().json;

let reasons = [];
try {
  let text = '';
  if (llmOutput.candidates && llmOutput.candidates[0]) {
    text = llmOutput.candidates[0].content.parts[0].text;
  }
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  reasons = JSON.parse(text);
  if (!Array.isArray(reasons)) reasons = [];
} catch (e) {
  reasons = [];
}

const reasonMap = new Map(reasons.map(r => [r.id, r.reason]));

const results = reranked.results.map(card => {
  let reason = reasonMap.get(card.id);
  if (!reason || reason.length > 150) {
    // Template fallback
    const parts = [];
    if (card.matched_role) parts.push(`You'd fill their ${card.matched_role} role`);
    if (card.factors.interest >= 0.6) parts.push(`shared interests in ${card.challenge || 'this area'}`);
    reason = parts.length > 0 ? parts.join(', and ') + '.' : `This team could use your skills.`;
  }
  return { ...card, reason };
});

// Remove internal fields
const cleaned = results.map(({ score, matched_skills, ...rest }) => rest);

const startTime = $('Webhook: match-teams').first().json.headers?.['x-start-time'];
const ms = startTime ? Date.now() - parseInt(startTime) : 0;

return [{ json: {
  profile: reranked.profile,
  results: cleaned,
  meta: {
    candidates: reranked.candidateCount,
    weights: reranked.weights,
    ms,
    fallback: false
  }
} }];
